export const dimensions = [
 ['Data', /\b(data|dataset|records|training|csv|labels)\b/i, /\b(provenance|data quality|validation|missing values|schema|labeling|labelling)\b/i, 'What evidence establishes that the input data is fit for the proposed use?', 'Data owner', 'Inspect a representative sample and record provenance, missing-value rates, schema failures, and label disagreements.'],
 ['Scale & performance', /\b(users|requests|traffic|real.time|latency|scale|concurrent)\b/i, /\b(p95|p99|load test|requests per second|concurrency limit|latency budget)\b/i, 'What measured load and latency envelope must the system support?', 'Technical lead', 'Replay a representative workload, record concurrency, p95 latency and errors, and agree an acceptance ceiling.'],
 ['Dependencies', /\b(api|vendor|third.party|integration|external|provider)\b/i, /\b(rate limit|timeout|fallback|sla|version pin|deprecation)\b/i, 'What happens to the critical workflow when an external dependency is unavailable?', 'Integration owner', 'Disable one named dependency in a test environment and record the user-visible result and recovery behavior.'],
 ['Legal & ethics', /\b(personal|customer data|patient|email|sensitive|pii|licensed)\b/i, /\b(consent|retention|deletion|lawful basis|license|licence|privacy review)\b/i, 'Who authorizes this data use, and what retention and deletion rules apply?', 'Data owner', 'Trace one record from collection through deletion and request the applicable permission and retention policy.'],
 ['People & operations', /\b(launch|production|deploy|release|support|operate)\b/i, /\b(on.call|runbook|incident owner|support owner|operations owner)\b/i, 'Who responds when the released system produces a wrong result outside working hours?', 'Delivery lead', 'Run a tabletop incident with a named responder and record escalation and recovery responsibilities.'],
 ['Failure & recovery', /\b(automat|payment|migration|write|delete|production|deploy|decision)/i, /\b(rollback|idempotenc|restore|recovery|dead.letter|reconciliation)\b/i, 'How is a partial or incorrect execution detected and reversed?', 'Technical lead', 'Interrupt a representative operation halfway through in a sandbox; check duplicate effects and demonstrate restoration.'],
 ['Economics', /\b(model|api|cloud|hosting|subscription|paid|inference|storage)\b/i, /\b(unit cost|cost per|budget cap|spend limit|unit economics)\b/i, 'What is the affordable cost per successful outcome at the intended volume?', 'Budget owner', 'Measure resource usage for a small representative batch and calculate cost per successful result using actual provider rates.'],
 ['Success & measurement', /./s, /\b(acceptance criteria|success metric|baseline|guardrail|precision|recall|success threshold)\b/i, 'Which measurable result would justify shipping, and which result would block release?', 'Product owner', 'Choose five representative cases, label expected outcomes with their owners, and agree acceptance and false-alarm thresholds.']
];
export function priority(axes){const v=['S','P','D','T','E'].map(k=>Number(axes[k]));if(v.some(x=>!Number.isInteger(x)||x<1||x>5))return null;return Math.round(v[0]*v[1]*v[2]*v[3]/v[4]);}
export function band(score){return score===null?'UNSCORED':score>=250?'CRITICAL':score>=100?'HIGH':score>=40?'MEDIUM':'LOW';}
export function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else if(!quoted&&cell!=='')throw Error('Unexpected quote in CSV');else quoted=!quoted;}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw Error('Unclosed quoted CSV field');if(cell||row.length){row.push(cell);rows.push(row);}return rows;}
export function analyze(documents){
 const docs=documents.filter(d=>d.text.trim());if(!docs.length)throw Error('Add project materials before running an audit.');
 const lines=docs.flatMap((d,di)=>d.text.split(/\r?\n/).map((text,i)=>({doc:d.name,docIndex:di,line:i+1,text}))).filter(l=>l.text.trim());
 const text=docs.map(d=>d.text).join('\n'), findings=[], coverage=[];
 const evidence=l=>({source:l.doc,docIndex:l.docIndex,line:l.line,quote:l.text});
 function add(f){findings.push({id:`F-${String(findings.length+1).padStart(2,'0')}`,axes:{S:null,P:null,D:null,T:null,E:null},status:'Open',...f});}
 for(const [name,trigger,covered,q,owner,test] of dimensions){const relevant=lines.find(l=>trigger.test(l.text));const support=lines.find(l=>covered.test(l.text)&&!(/\b(TBD|TODO|TBC|unassigned|no|not|without|none)\b/i.test(l.text)));coverage.push({name,state:support?'Mention found':relevant?'Review needed':'No context',evidence:support?evidence(support):null});if(relevant&&!support)add({type:'C',dimension:name,title:q,confidence:'MEDIUM',basis:'Inference · keyword-based candidate',missing:`No matching ${name.toLowerCase()} control language was found in the supplied text. Equivalent wording or separate documents may resolve this.`,evidence:[evidence(relevant)],impact:`The cited scope makes ${name.toLowerCase()} relevant. An unresolved answer could change the design or release decision; impact and timing need owner confirmation.`,recommendation:`${owner}: ${test}`,verify:test,owner});}
 const automated=lines.find(l=>/\b(automated|automatically|autonomous)\b/i.test(l.text)&&/\b(decision|write|routing|approve|delete|payment|assign)/i.test(l.text));
 const evaluation=lines.find(l=>/\b(human review|approval gate|holdout|evaluation set|error threshold|precision|recall)\b/i.test(l.text)&&!(/\b(no|not|without|TBD)\b/i.test(l.text)));
 if(automated&&!evaluation)add({type:'A',dimension:'Decision quality',title:'Automated decisions appear to depend on unverified output quality',confidence:'MEDIUM',basis:'Inference · confirm with decision owner',missing:'The cited automated decision implies that its output is usable downstream. No matching evaluation or human-review gate was found. The holder of this assumption is not identified in the supplied materials.',evidence:[evidence(automated)],impact:'If the implied assumption is false, incorrect decisions could reach the downstream workflow before review. The actual error rate and timing are unknown.',recommendation:'Product owner: label a representative evaluation set and identify the approval gate for consequential errors.',verify:'Replay five owner-reviewed cases, compare decisions with expected outcomes, and trace whether an incorrect decision reaches a downstream action.',owner:'Product owner'});
 const placeholders=lines.filter(l=>/\b(TBD|TODO|TBC|placeholder|owner\s*:\s*unassigned)\b/i.test(l.text));if(placeholders.length)add({type:'B',dimension:'People & operations',title:'Unresolved placeholders remain in the supplied materials',confidence:'HIGH',basis:'Directly observed',missing:`${placeholders.length} source line(s) contain unresolved template or assignment markers.`,evidence:placeholders.slice(0,5).map(evidence),impact:'If these lines govern release work, implementation can proceed before the underlying decision is made. Their critical-path relevance is not supplied.',recommendation:'Delivery lead: assign an owner and resolution date to each cited placeholder this week.',verify:'Ask each named owner to replace the marker with an approved decision, or mark it explicitly out of scope.',owner:'Delivery lead',axes:{S:null,P:5,D:null,T:null,E:1}});
 const claims=new Map();for(const l of lines){const m=l.text.match(/^\s*(launch date|release date|budget|data retention|retention period|project owner|success threshold|latency target)\s*:\s*(.+?)\s*$/i);if(m&&!/\b(TBD|TODO|TBC)\b/i.test(m[2])){const key=m[1].toLowerCase();if(!claims.has(key))claims.set(key,[]);claims.get(key).push({value:m[2].trim().toLowerCase(),l});}}
 for(const [key,values] of claims){if(new Set(values.map(v=>v.value)).size>1)add({type:'D',dimension:'Definition',title:`Conflicting ${key} declarations require reconciliation`,confidence:'MEDIUM',basis:'Conflicting text · scope not verified',missing:'The same labeled field has different values. Version, scenario, and scope differences must be ruled out before treating this as a defect.',evidence:values.slice(0,4).map(v=>evidence(v.l)),impact:`Teams using different ${key} values could make incompatible implementation or release decisions.`,recommendation:`Project owner: confirm whether the cited values refer to the same scope and designate the authoritative value.`,verify:'Compare document versions and scope with the project owner; retire obsolete declarations or label scenarios.',owner:'Project owner'});}
 const profiles=[];for(const [docIndex,d] of docs.entries()){if(!/\.csv$/i.test(d.name))continue;try{const rows=parseCSV(d.text);if(!rows.length)continue;const headers=rows[0],data=rows.slice(1);let malformed=0,missing=0;data.forEach(r=>{if(r.length!==headers.length)malformed++;for(let c=0;c<headers.length;c++)if(!(r[c]||'').trim())missing++;});profiles.push({source:d.name,rows:data.length,columns:headers.length,missing,malformed});if(missing||malformed)add({type:'B',dimension:'Data',title:`${d.name}: dataset structure needs a data-owner decision`,confidence:'HIGH',basis:'Computed from supplied CSV',missing:`${missing} empty or absent cells; ${malformed} records differ from the header width (${headers.length}). Empty values may be legitimate; semantic validity is not established.`,evidence:[{source:d.name,docIndex,line:1,quote:d.text.split(/\r?\n/)[0]}],impact:'A consumer requiring complete rectangular records could reject or misinterpret these rows during ingestion.',recommendation:'Data owner: define nullable columns and reject or repair records that violate the agreed schema.',verify:'Compare the computed counts with the ingestion schema and inspect each rejected record before processing.',owner:'Data owner',axes:{S:null,P:5,D:null,T:null,E:1}});}catch(e){profiles.push({source:d.name,error:e.message});add({type:'B',dimension:'Data',title:`${d.name}: CSV cannot be parsed`,confidence:'HIGH',basis:'Parser error',missing:e.message,evidence:[{source:d.name,docIndex,line:1,quote:d.text.split(/\r?\n/)[0]}],impact:'Dataset profiling cannot proceed until the file is valid CSV.',recommendation:'Data owner: re-export as UTF-8 CSV with correctly escaped quotes.',verify:'Re-import the corrected file and confirm its row and column counts.',owner:'Data owner',axes:{S:null,P:5,D:1,T:null,E:1}});}}
 findings.sort((a,b)=>Number(b.dimension==='Success & measurement')-Number(a.dimension==='Success & measurement'));findings.forEach((f,i)=>f.id=`F-${String(i+1).padStart(2,'0')}`);
 const thin=text.trim().split(/\s+/).length<120;
 return {createdAt:new Date().toISOString(),engine:'Local rules engine v1 — no language model',thin,documents:docs,findings,coverage,profiles,model:[`Objective / scope excerpt: ${lines[0].text}`,`Inputs reviewed: ${docs.map(d=>d.name).join(', ')}`,`Source coverage: ${lines.length} nonempty lines; ${docs.length} documents.`,`Actors: require owner confirmation; automated role extraction is not available.`,`Critical path: not reconstructed by this rules engine.`,`Success: ${coverage[7].state==='Mention found'?'Measurement-related language found; adequacy requires review.':'NOT DEFINED in recognized control language; verify equivalent wording.'}`]};
}
export function sorted(findings){return [...findings].sort((a,b)=>(priority(b.axes)??-1)-(priority(a.axes)??-1));}
export function markdown(report){const lines=['# SENTINEL audit',`Engine: ${report.engine}`,`Generated: ${report.createdAt}`,'','## PROJECT MODEL',...report.model.map(x=>`- ${x}`),'','## TOP RISKS'];if(report.thin)lines.push('Provisional: thin input. Request project specifications and operating context before making release decisions.');for(const f of sorted(report.findings).slice(0,10)){const n=priority(f.axes);lines.push('',`### ${f.id} [TYPE ${f.type}] — ${f.title}`,`Score: ${n===null?'Not computable — confirm all five axes':`(${f.axes.S}×${f.axes.P}×${f.axes.D}×${f.axes.T})/${f.axes.E} = ${n} → ${band(n)} (reviewer ratings)`} | Confidence: ${f.confidence}`,`Status: ${f.status}`,`Missing / Overlooked: ${f.missing}`,`Evidence: ${f.evidence.map(e=>`${JSON.stringify(e.quote)} — ${e.source}, line ${e.line}`).join('; ')}`,`Why it matters: ${f.impact}`,`Recommendation: ${f.recommendation}`,`Verify it: ${f.verify}`);}lines.push('','## DECISION-FORCING QUESTIONS',...report.findings.filter(f=>f.type==='C').slice(0,8).map((f,i)=>`${i+1}. ${f.title} — ${f.impact} Source: ${f.owner}.`));const conflicts=report.findings.filter(f=>f.type==='D');if(conflicts.length)lines.push('','## CONTRADICTIONS',...conflicts.map(f=>`${f.title}\n${f.evidence.map(e=>`- ${JSON.stringify(e.quote)} — ${e.source}:${e.line}`).join('\n')}`));lines.push('','## INPUTS THAT WOULD CHANGE MY MIND','1. Current specification and acceptance criteria.','2. Owner-reviewed examples of expected outcomes and false alarms.','3. Operating constraints, architecture and dependency contracts.','4. Representative data with schema and provenance.','5. Named owners, budget and release schedule.','','## VERDICT',`${report.findings.length} structural observations and review candidates; this is not a complete semantic audit. ${report.findings.some(f=>f.dimension==='Success & measurement')?'Resolve acceptance criteria before using these findings for a release decision.':'Validate inferred gaps with project owners.'} This week, review cited evidence and run the attached verification steps.`);return lines.join('\n');}
